-- =====================================================================
-- FlowPilot V1.0 MySQL 8.0 schema
--
-- Applied automatically by Flyway on start-up.
-- Conventions:
--   * BIGINT primary keys generated by the application layer (snowflake).
--   * DATETIME(3) millisecond precision, UTC.
--   * InnoDB / utf8mb4.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. sys_user
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sys_user (
    id BIGINT PRIMARY KEY,
    username VARCHAR(64) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    nickname VARCHAR(64),
    email VARCHAR(128),
    role VARCHAR(32) NOT NULL DEFAULT 'USER',
    status TINYINT NOT NULL DEFAULT 1,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
        ON UPDATE CURRENT_TIMESTAMP(3),

    UNIQUE KEY uk_username (username),
    UNIQUE KEY uk_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- 2. workflow_definition
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS workflow_definition (
    id BIGINT PRIMARY KEY,
    name VARCHAR(128) NOT NULL,
    description VARCHAR(512),
    category VARCHAR(64),
    owner_id BIGINT NOT NULL,
    latest_version INT NOT NULL DEFAULT 1,
    status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
        ON UPDATE CURRENT_TIMESTAMP(3),

    KEY idx_owner_id (owner_id),
    KEY idx_category_status (category, status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- 3. workflow_version (immutable once published)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS workflow_version (
    id BIGINT PRIMARY KEY,
    workflow_id BIGINT NOT NULL,
    version INT NOT NULL,
    definition_json JSON NOT NULL,
    definition_hash CHAR(64) NOT NULL,
    status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',
    created_by BIGINT NOT NULL,
    published_at DATETIME(3),
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

    UNIQUE KEY uk_workflow_version (workflow_id, version),
    UNIQUE KEY uk_workflow_hash (workflow_id, definition_hash)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- 4. workflow_execution
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS workflow_execution (
    id BIGINT PRIMARY KEY,
    workflow_id BIGINT NOT NULL,
    workflow_version_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,

    execution_no VARCHAR(64) NOT NULL,
    status VARCHAR(32) NOT NULL,

    -- The key of the caller. A repeated request with the same key returns the same execution
    -- instead of starting a second one.
    idempotency_key VARCHAR(128),

    input_json JSON,
    output_json JSON,

    current_node_count INT NOT NULL DEFAULT 0,
    completed_node_count INT NOT NULL DEFAULT 0,
    failed_node_count INT NOT NULL DEFAULT 0,

    -- monotonically increasing event sequence, used for SSE resume
    event_sequence BIGINT NOT NULL DEFAULT 0,
    -- cooperative cancellation flag, set before the final CANCELED state
    cancel_requested TINYINT NOT NULL DEFAULT 0,
    cancel_reason VARCHAR(128),

    error_code VARCHAR(64),
    error_message TEXT,

    version BIGINT NOT NULL DEFAULT 0,

    started_at DATETIME(3),
    finished_at DATETIME(3),

    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
        ON UPDATE CURRENT_TIMESTAMP(3),

    UNIQUE KEY uk_execution_no (execution_no),
    UNIQUE KEY uk_execution_idempotency (user_id, idempotency_key),
    KEY idx_user_created (user_id, created_at),
    KEY idx_workflow_status (workflow_id, status),
    KEY idx_status_created (status, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- 5. node_execution (one logical execution per node)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS node_execution (
    id BIGINT PRIMARY KEY,
    workflow_execution_id BIGINT NOT NULL,
    node_key VARCHAR(128) NOT NULL,
    node_type VARCHAR(32) NOT NULL,

    status VARCHAR(32) NOT NULL,

    input_json JSON,
    output_json JSON,

    current_attempt INT NOT NULL DEFAULT 0,
    max_attempts INT NOT NULL DEFAULT 3,

    worker_id VARCHAR(128),
    lease_token BIGINT NOT NULL DEFAULT 0,
    lease_expire_at DATETIME(3),
    heartbeat_at DATETIME(3),

    -- The moment the node may be retried. The delay of the retry policy is persisted here
    -- instead of being slept on in a worker thread.
    next_retry_at DATETIME(3),

    error_code VARCHAR(64),
    error_message TEXT,

    version BIGINT NOT NULL DEFAULT 0,

    started_at DATETIME(3),
    finished_at DATETIME(3),

    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
        ON UPDATE CURRENT_TIMESTAMP(3),

    UNIQUE KEY uk_execution_node (
        workflow_execution_id,
        node_key
    ),

    KEY idx_status_lease (status, lease_expire_at),
    KEY idx_status_retry (status, next_retry_at),
    KEY idx_workflow_status (workflow_execution_id, status),
    KEY idx_worker_status (worker_id, status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- 6. node_execution_attempt (one row per physical execution attempt)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS node_execution_attempt (
    id BIGINT PRIMARY KEY,
    node_execution_id BIGINT NOT NULL,
    attempt_no INT NOT NULL,

    status VARCHAR(32) NOT NULL,

    worker_id VARCHAR(128),
    lease_token BIGINT NOT NULL,

    input_snapshot JSON,
    output_snapshot JSON,

    error_code VARCHAR(64),
    error_message TEXT,

    started_at DATETIME(3),
    finished_at DATETIME(3),

    duration_ms BIGINT,

    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

    UNIQUE KEY uk_node_attempt (
        node_execution_id,
        attempt_no
    ),

    KEY idx_node_status (node_execution_id, status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- 7. execution_event (append-only audit + SSE source)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS execution_event (
    id BIGINT PRIMARY KEY,
    workflow_execution_id BIGINT NOT NULL,
    node_execution_id BIGINT,

    event_type VARCHAR(64) NOT NULL,
    event_data JSON,

    sequence_no BIGINT NOT NULL,

    operator_id BIGINT,
    trace_id VARCHAR(64),

    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

    UNIQUE KEY uk_execution_sequence (
        workflow_execution_id,
        sequence_no
    ),

    KEY idx_execution_created (
        workflow_execution_id,
        created_at
    ),

    KEY idx_node_created (
        node_execution_id,
        created_at
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- 8. message_outbox (transactional outbox)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS message_outbox (
    id BIGINT PRIMARY KEY,
    message_id VARCHAR(64) NOT NULL,
    message_type VARCHAR(64) NOT NULL,

    aggregate_type VARCHAR(32) NOT NULL,
    aggregate_id BIGINT NOT NULL,

    routing_key VARCHAR(128) NOT NULL,
    payload JSON NOT NULL,

    status VARCHAR(32) NOT NULL DEFAULT 'PENDING',

    retry_count INT NOT NULL DEFAULT 0,
    next_retry_at DATETIME(3),

    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    published_at DATETIME(3),

    UNIQUE KEY uk_message_id (message_id),

    KEY idx_status_retry (
        status,
        next_retry_at,
        created_at
    ),

    KEY idx_aggregate (
        aggregate_type,
        aggregate_id
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- 9. message_consume_record (consumer side idempotency)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS message_consume_record (
    id BIGINT PRIMARY KEY,
    consumer_name VARCHAR(128) NOT NULL,
    message_id VARCHAR(64) NOT NULL,

    status VARCHAR(32) NOT NULL,
    consumed_at DATETIME(3),

    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

    UNIQUE KEY uk_consumer_message (
        consumer_name,
        message_id
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- 10. approval_record
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS approval_record (
    id BIGINT PRIMARY KEY,
    workflow_execution_id BIGINT NOT NULL,
    node_execution_id BIGINT NOT NULL,

    approval_type VARCHAR(64) NOT NULL,

    status VARCHAR(32) NOT NULL DEFAULT 'PENDING',

    title VARCHAR(256),
    description TEXT,

    request_data JSON,
    decision_data JSON,

    requested_at DATETIME(3),
    decided_at DATETIME(3),

    approver_id BIGINT,
    comment TEXT,

    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

    KEY idx_approver_status (
        approver_id,
        status
    ),

    KEY idx_execution_status (
        workflow_execution_id,
        status
    ),

    KEY idx_node_status (
        node_execution_id,
        status
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- 11. agent_invocation (Java <-> LangGraph correlation)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS agent_invocation (
    id BIGINT PRIMARY KEY,
    invocation_no VARCHAR(64) NOT NULL,

    workflow_execution_id BIGINT NOT NULL,
    node_execution_id BIGINT NOT NULL,
    attempt_no INT NOT NULL,

    agent_type VARCHAR(64) NOT NULL,

    thread_id VARCHAR(128) NOT NULL,
    checkpoint_id VARCHAR(128),

    status VARCHAR(32) NOT NULL,

    model_name VARCHAR(128),
    token_input BIGINT NOT NULL DEFAULT 0,
    token_output BIGINT NOT NULL DEFAULT 0,

    error_code VARCHAR(64),
    error_message TEXT,

    started_at DATETIME(3),
    finished_at DATETIME(3),

    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
        ON UPDATE CURRENT_TIMESTAMP(3),

    UNIQUE KEY uk_invocation_no (invocation_no),
    UNIQUE KEY uk_thread_id (thread_id),

    KEY idx_node_attempt (
        node_execution_id,
        attempt_no
    ),

    KEY idx_workflow_execution (
        workflow_execution_id
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
-- 12. analysis_report
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS analysis_report (
    id BIGINT PRIMARY KEY,
    workflow_execution_id BIGINT NOT NULL,

    report_no VARCHAR(64) NOT NULL,
    title VARCHAR(256) NOT NULL,

    repository_url VARCHAR(512),

    report_type VARCHAR(64) NOT NULL,
    status VARCHAR(32) NOT NULL,

    summary TEXT,

    content_json JSON,
    markdown_content MEDIUMTEXT,

    storage_url VARCHAR(1024),
    content_hash CHAR(64),

    generated_at DATETIME(3),
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

    UNIQUE KEY uk_report_no (report_no),
    KEY idx_execution (workflow_execution_id),
    KEY idx_status_created (status, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
